  ("إلى ماذا يطلب الله أن ينظر الإنسان؟","What does Allah ask a person to look at?",[("طعامه","His food"),("ملابسه","His clothes"),("ألعابه","His toys")],0),
  ("ممن يفرّ المرء يوم القيامة؟","Who will a person run from on the Day of Judgment?",[("من أخيه وأمه وأبيه","His brother, mother and father"),("من الأسد","A lion"),("من المطر","The rain")],0),
